import { useState, useEffect, useRef, useCallback } from 'react';
import { useApp } from '../context/AppContext';
import IndiaMap from '../components/map/IndiaMap';

// ─────────────────────────────────────────────────────────────────────────────
// FEATURED CAROUSEL
// ─────────────────────────────────────────────────────────────────────────────

function FeaturedCarousel({ images }) {
  const [current, setCurrent] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(true);
  const intervalRef = useRef(null);

  const extended = [...images, images[0]];

  const stopAuto = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, []);

  const startAuto = useCallback(() => {
    stopAuto();
    intervalRef.current = setInterval(() => {
      setCurrent(c => c + 1);
    }, 3000);
  }, [stopAuto]);

  const goTo = (n) => {
    setIsTransitioning(true);
    setCurrent(n);
    startAuto();
  };

  useEffect(() => {
    if (current === images.length) {
      const timer = setTimeout(() => {
        setIsTransitioning(false);
        setCurrent(0);
      }, 600);
      return () => clearTimeout(timer);
    }
  }, [current, images.length]);

  useEffect(() => {
    if (!isTransitioning) {
      const timer = setTimeout(() => setIsTransitioning(true), 50);
      return () => clearTimeout(timer);
    }
  }, [isTransitioning]);

  useEffect(() => {
    startAuto();
    return () => stopAuto();
  }, [startAuto, stopAuto]);

  if (!images?.length) return null;

  const activeDot = current === images.length ? 0 : current;

  return (
    <div
      style={{
        position: 'relative',
        borderRadius: 16,
        overflow: 'hidden',
        border: '1px solid var(--border)',
        background: '#000',
        width: '100%',         /* ← ensure full container width */
      }}
      onMouseEnter={stopAuto}
      onMouseLeave={startAuto}
    >
      {/* Track */}
      <div
        style={{
          display: 'flex',
          width: '100%',
          transition: isTransitioning
            ? 'transform .6s cubic-bezier(.4,0,.2,1)'
            : 'none',
          transform: `translateX(-${current * 100}%)`,
        }}
      >
        {extended.map((img, i) => {
          const baseUrl = img.imageUrl || null;
          console.log("baseUrl :::" + baseUrl);
          return (
            <div
              key={i}
              style={{
                minWidth: '100%',
                width: '100%',
                position: 'relative',
                flexShrink: 0,
                overflow: 'hidden',
                background: '#000',
              }}
            >
              {baseUrl ? (
                <img
                  src={baseUrl}
                  alt={img.display_name}
                  loading={i === 0 ? 'eager' : 'lazy'}
                  style={{
                    width: '100%',
                    height: 'auto',
                    display: 'block',
                  }}
                />
              ) : null}

              {/* Fallback */}
              <div
                style={{
                  display: baseUrl ? 'none' : 'flex',
                  height: '100%',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '4rem',
                  background: 'var(--bg3)',
                }}
              >
                🦋
              </div>

              {/* Gradient */}
              <div
                style={{
                  position: 'absolute',
                  inset: 0,
                  background:
                    'linear-gradient(to top, rgba(0,0,0,.75) 0%, transparent 50%)',
                  pointerEvents: 'none',
                }}
              />

              {/* Caption */}
              <div
                style={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  right: 0,
                  padding: '1.5rem',
                }}
              >
                <div
                  style={{
                    fontFamily: 'var(--ff)',
                    fontSize: '1.2rem',
                    fontWeight: 600,
                    color: '#fff',
                    marginBottom: 4,
                  }}
                >
                  {img.display_name}
                </div>

                {img.latitude &&
                  img.longitude &&
                  (img.latitude !== 0 || img.longitude !== 0) && (
                    <div
                      style={{
                        fontSize: '.8rem',
                        color: 'rgba(255,255,255,.7)',
                      }}
                    >
                      📍 {parseFloat(img.latitude).toFixed(3)}°N ·{' '}
                      {parseFloat(img.longitude).toFixed(3)}°E
                    </div>
                  )}
              </div>
            </div>
          );
        })}
      </div>

      {/* Prev / Next */}
      {[{ dir: -1, side: 'left', label: '←' }, { dir: 1, side: 'right', label: '→' }].map(
        ({ dir, side, label }) => (
          <button
            key={side}
            onClick={() => {
              if (dir === -1 && current === 0) {
                setIsTransitioning(false);
                setCurrent(images.length);
                setTimeout(() => {
                  setIsTransitioning(true);
                  setCurrent(images.length - 1);
                  startAuto();
                }, 50);
                return;
              }
              goTo(current + dir);
            }}
            style={{
              position: 'absolute',
              top: '50%',
              [side]: 12,
              transform: 'translateY(-50%)',
              background: 'rgba(255,255,255,.15)',
              border: '1px solid rgba(255,255,255,.3)',
              borderRadius: '50%',
              width: 40,
              height: 40,
              cursor: 'pointer',
              color: '#fff',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 2,
            }}
          >
            {label}
          </button>
        )
      )}

      {/* Dots */}
      <div
        style={{
          position: 'absolute',
          bottom: '1rem',
          right: '1.5rem',
          display: 'flex',
          gap: 6,
          zIndex: 2,
        }}
      >
        {images.map((_, i) => (
          <button
            key={i}
            onClick={() => goTo(i)}
            style={{
              width: activeDot === i ? 20 : 6,
              height: 6,
              borderRadius: 3,
              border: 'none',
              cursor: 'pointer',
              background:
                activeDot === i ? '#fff' : 'rgba(255,255,255,.4)',
              transition: 'all .3s',
              padding: 0,
            }}
          />
        ))}
      </div>

      {/* Progress bar */}
      <div
        style={{
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          height: 3,
          background: 'rgba(255,255,255,.2)',
          zIndex: 2,
        }}
      >
        <div
          key={current}
          style={{
            height: '100%',
            background: '#fff',
            animation: 'carouselProgress 3s linear forwards',
          }}
        />
      </div>

      <style>{`
        @keyframes carouselProgress {
          from { width: 0% }
          to { width: 100% }
        }
      `}</style>
    </div>
  );
}

